import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#a9c1ac');
scene.fog=new THREE.FogExp2('#a9c1ac',0.009);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,240);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;
scene.add(new THREE.HemisphereLight('#e7f2dc','#405a39',2.1));
const sun=new THREE.DirectionalLight('#fff0cb',3.2);sun.position.set(-35,58,25);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,roughness=.88)=>new THREE.MeshStandardMaterial({color,roughness});
const groundMat=mat('#758c56');
const ground=new THREE.Mesh(new THREE.PlaneGeometry(240,240,1,1),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.14;ground.receiveShadow=true;scene.add(ground);
const group=new THREE.Group();scene.add(group);
const rand=(a,b)=>a+Math.random()*(b-a);
const materials={leaf:[mat('#416d45'),mat('#517d4c'),mat('#6a8c51'),mat('#355d40')],wood:mat('#76543a'),bark:mat('#604732'),stone:[mat('#8c9487'),mat('#737f78'),mat('#a3a392')],berry:mat('#718b4e'),flower:mat('#e4d58c')};
// Hand-shaped distant mountains
for(let i=0;i<13;i++){const h=rand(12,27),r=rand(10,21);const m=new THREE.Mesh(new THREE.ConeGeometry(r,h,6),mat(i%2?'#84967a':'#748b75'));m.position.set(-77+i*13,h/2-2,-75-rand(0,20));m.rotation.y=rand(0,6);m.castShadow=true;scene.add(m);const snow=new THREE.Mesh(new THREE.ConeGeometry(r*.43,h*.42,6),mat('#c5cbb0'));snow.position.set(m.position.x,h*.78-2,m.position.z);scene.add(snow)}
// Curving stream through the grove
const waterMat=new THREE.MeshStandardMaterial({color:'#69a6a1',roughness:.2,metalness:.1,transparent:true,opacity:.88});
for(let i=0;i<14;i++){const z=-48+i*7.5,x=14+Math.sin(i*.48)*9;const water=new THREE.Mesh(new THREE.CylinderGeometry(3.1,3.8,0.12,12),waterMat);water.rotation.z=Math.PI/2;water.position.set(x,-.06,z);water.scale.set(1,1,.75);scene.add(water);const bank=new THREE.Mesh(new THREE.CylinderGeometry(4.2,4.6,.18,12),mat('#9a9a68'));bank.rotation.z=Math.PI/2;bank.position.set(x,-.13,z);bank.scale.set(1,1,.8);scene.add(bank)}
// Stylized tree made from trunks, layered canopies and a little warm foliage
function makeTree(x,z,scale=1){const t=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.24*scale,.5*scale,3.3*scale,7),materials.bark);trunk.position.y=1.45*scale;trunk.castShadow=true;t.add(trunk);for(let n=0;n<3;n++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry((1.45-n*.2)*scale,1),materials.leaf[(Math.random()*4)|0]);crown.position.set(rand(-.24,.24)*scale,(3.0+n*.73)*scale,rand(-.2,.2)*scale);crown.scale.set(1,1.08,.96);crown.castShadow=true;crown.receiveShadow=true;t.add(crown)}const glint=new THREE.Mesh(new THREE.IcosahedronGeometry(.45*scale,0),mat('#95a966'));glint.position.set(.56*scale,4.2*scale,.2*scale);t.add(glint);t.position.set(x,0,z);group.add(t);return t}
function makeRock(x,z,s=1){const mesh=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),materials.stone[(Math.random()*3)|0]);mesh.position.set(x,s*.48,z);mesh.scale.set(1,rand(.65,1.15),rand(.8,1.2));mesh.rotation.set(rand(-.3,.3),rand(0,6),rand(-.2,.2));mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh}
for(let i=0;i<92;i++){let x=rand(-54,54),z=rand(-54,54);if(Math.abs(x)<8&&Math.abs(z)<9)continue;if(x>8&&x<25&&Math.abs(z)<49)continue;makeTree(x,z,rand(.65,1.3))}
for(let i=0;i<74;i++){let x=rand(-42,42),z=rand(-40,42);if(Math.abs(x)<7&&Math.abs(z)<8)continue;makeRock(x,z,rand(.28,.92))}
// Fern-like ground plants and small wildflowers
for(let i=0;i<74;i++){const x=rand(-37,37),z=rand(-35,37);const plant=new THREE.Group();for(let j=0;j<5;j++){const f=new THREE.Mesh(new THREE.ConeGeometry(.16,.95,5),mat(j%2?'#658c53':'#86a65c'));f.position.set(rand(-.3,.3),.4,rand(-.25,.25));f.rotation.z=rand(-.4,.4);plant.add(f)}plant.position.set(x,0,z);group.add(plant)}
// Resource nodes have clearly visible, collectible silhouettes
const resources=[];
const kinds={wood:{label:'Fallen branch',icon:'⌁',color:'#b57b4a',yield:{wood:2},emoji:'🪵'},stone:{label:'Flint deposit',icon:'◆',color:'#bac0b1',yield:{stone:1},emoji:'◈'},berries:{label:'Wild berries',icon:'●',color:'#d77d72',yield:{berries:2},emoji:'◉'},plant:{label:'Healing herb',icon:'❋',color:'#a7c77a',yield:{plants:1},emoji:'❋'}};
function makeNode(type,x,z){const g=new THREE.Group();const k=kinds[type];if(type==='wood'){for(let i=0;i<3;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.16,.18,1.65,7),materials.wood);log.rotation.z=Math.PI/2+rand(-.1,.1);log.position.set(rand(-.22,.22),.2+i*.08,rand(-.2,.2));log.castShadow=true;g.add(log);const end=new THREE.Mesh(new THREE.CircleGeometry(.15,8),mat('#c39a68'));end.position.set(.82,.2+i*.08,rand(-.2,.2));end.rotation.y=Math.PI/2;g.add(end)}}else if(type==='stone'){const a=makeRock(0,0,.62);a.position.set(0,.35,0);group.remove(a);g.add(a);for(let i=0;i<3;i++){const shard=new THREE.Mesh(new THREE.DodecahedronGeometry(.15,0),materials.stone[0]);shard.position.set(rand(-.5,.5),.4,rand(-.35,.35));g.add(shard)}}else{const bush=new THREE.Mesh(new THREE.IcosahedronGeometry(type==='berries'?.65:.42,1),mat(type==='berries'?'#55794c':'#71935a'));bush.position.y=.48;bush.scale.y=.75;g.add(bush);if(type==='berries')for(let i=0;i<8;i++){const berry=new THREE.Mesh(new THREE.SphereGeometry(.095,8,7),mat(i%2?'#d57f7a':'#e5a078'));berry.position.set(rand(-.45,.45),rand(.35,.8),rand(-.45,.45));g.add(berry)}else for(let i=0;i<5;i++){const flower=new THREE.Mesh(new THREE.SphereGeometry(.095,7,6),materials.flower);flower.position.set(rand(-.3,.3),rand(.65,.95),rand(-.3,.3));g.add(flower)}}g.position.set(x,0,z);group.add(g);const node={type,x,z,mesh:g,active:true,phase:rand(0,7)};resources.push(node);return node}
for(let i=0;i<9;i++)makeNode('wood',rand(-22,20),rand(-22,21));for(let i=0;i<9;i++)makeNode('stone',rand(-25,20),rand(-22,22));for(let i=0;i<9;i++)makeNode('berries',rand(-22,22),rand(-20,22));for(let i=0;i<8;i++)makeNode('plant',rand(-23,23),rand(-21,22));
// Original adventurer, built from simple shaded forms
const player=new THREE.Group();scene.add(player);player.position.set(0,0,0);player.rotation.y=0;
const skin=mat('#dfb28c'),hair=mat('#252e2d'),cloth=mat('#d2c49c'),coat=mat('#bc654a'),dark=mat('#344c43');
const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.64,5,9),coat);torso.position.y=1.28;torso.castShadow=true;player.add(torso);
const shirt=new THREE.Mesh(new THREE.CapsuleGeometry(.3,.4,4,8),cloth);shirt.position.set(0,1.33,.06);shirt.scale.set(1,.9,.83);player.add(shirt);
const head=new THREE.Mesh(new THREE.SphereGeometry(.33,12,10),skin);head.position.set(0,2.1,0);head.castShadow=true;player.add(head);
const haircap=new THREE.Mesh(new THREE.SphereGeometry(.35,10,8,0,Math.PI*2,0,Math.PI*.62),hair);haircap.position.set(0,2.2,-.015);haircap.scale.set(1.05,1,1);player.add(haircap);
for(let s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,7,6),mat('#30423b'));eye.position.set(s*.12,2.13,.296);player.add(eye);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.55,4,7),skin);arm.position.set(s*.49,1.27,0);arm.rotation.z=s*.16;player.add(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.15,.55,4,7),dark);leg.position.set(s*.2,.48,0);player.add(leg);const boot=new THREE.Mesh(new THREE.SphereGeometry(.18,8,7),mat('#493c31'));boot.scale.set(1,.62,1.4);boot.position.set(s*.2,.13,.06);player.add(boot)}
// Soft graphic camp marker
const camp=new THREE.Group();const firewood=new THREE.Mesh(new THREE.CylinderGeometry(.09,.1,1.05,7),materials.wood);firewood.rotation.z=Math.PI/2;firewood.position.y=.13;camp.add(firewood);const firewood2=firewood.clone();firewood2.rotation.y=.5;firewood2.rotation.z=.45;firewood2.position.y=.22;camp.add(firewood2);camp.position.set(-4,0,4);scene.add(camp);

