const state={wood:0,stone:0,berries:0,plants:0,science:0,health:100,hunger:84,thirst:72,level:1,tools:[],buildings:[],day:1,time:8,started:false,paused:false};
const saved=localStorage.getItem('stone-world-save');
if(saved){try{Object.assign(state,JSON.parse(saved));document.querySelector('#continue-btn').style.display='block'}catch{}}
const keys={};let yaw=0,pitch=.18,moveX=0,moveZ=0,nearest=null,activePanel=null,lastTime=performance.now(),survivalClock=0,toastTimer;
const resourceTypes=['wood','stone','berries','plants'];
const icons={wood:'🪵',stone:'◈',berries:'●',plants:'❋'};
function updateHud(){for(const t of resourceTypes){const el=document.querySelector(`#count-${t}`);if(el)el.textContent=state[t]}for(const key of ['health','hunger','thirst']){const v=Math.round(state[key]);document.querySelector(`#${key}-value`).textContent=v;document.querySelector(`#${key}-bar`).style.width=v+'%'}document.querySelector('#science-value').textContent=`${state.science} / ${state.level===1?30:state.level===2?90:180}`;document.querySelector('#level').textContent=String(state.level).padStart(2,'0');document.querySelector('#age-label').textContent=['STONE AGE','BRONZE AGE','IRON AGE','INDUSTRIAL AGE','MODERN AGE'][Math.min(4,state.level-1)];const got= Math.min(100,Math.floor((Math.min(state.wood,3)+Math.min(state.stone,2))/5*100));document.querySelector('#quest-progress').textContent=got+'%';document.querySelector('#quest-text').textContent=got>=100?'A new beginning':'Gather the first materials';document.querySelector('#quest-sub').textContent=got>=100?'Craft a stone axe to unlock the wilds.':'Collect 3 wood and 2 stone to begin.';}
function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function saveGame(){localStorage.setItem('stone-world-save',JSON.stringify(state));showToast('JOURNEY SAVED · PROGRESS SECURED')}
function setPanel(panel){const drawer=document.querySelector('#drawer');if(activePanel===panel){activePanel=null;drawer.classList.add('hidden');document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));return}activePanel=panel;drawer.classList.remove('hidden');document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));renderPanel(panel)}
function renderPanel(panel){const titles={bag:['SURVIVOR\'S KIT','Inventory'],craft:['FIELDCRAFT','Crafting'],build:['SETTLEMENT','Build'],research:['ANCIENT KNOWLEDGE','Research']};document.querySelector('#drawer-eyebrow').textContent=titles[panel][0];document.querySelector('#drawer-title').textContent=titles[panel][1];const content=document.querySelector('#drawer-content');
 if(panel==='bag'){content.innerHTML=`<div class="section-label">CARRIED RESOURCES</div><div class="inventory-grid">${[['wood','🪵','Timber'],['stone','◈','Stone'],['berries','●','Berries'],['plants','❋','Herbs']].map(([key,icon,label])=>`<div class="inventory-cell"><span>${icon}</span><small>${state[key]}</small><b>${label}</b></div>`).join('')}</div><div class="section-label">EQUIPPED</div><div class="inventory-cell" style="min-height:64px"><span>${state.tools.includes('Stone axe')?'🪓':'✦'}</span><b>${state.tools.length?state.tools.join(' · '):'Empty hands'}</b></div><p class="recipe-note">Resources are gathered in the wild. Walk near a marked resource and press <b>E</b> (or tap the action button).</p>`}
 if(panel==='craft'){content.innerHTML=`<div class="section-label">RECIPES · STONE AGE</div>${recipeRow('🪓','Stone axe','2 wood · 2 stone','Stone axe',{wood:2,stone:2})}${recipeRow('⌁','Stone knife','1 wood · 2 stone','Stone knife',{wood:1,stone:2})}${recipeRow('🔥','Campfire','3 wood · 1 stone','Campfire',{wood:3,stone:1})}<p class="recipe-note">Tools improve your ability to explore. Craft a campfire to endure the first night.</p>`;wireRecipes()}
 if(panel==='build'){content.innerHTML=`<div class="section-label">PLACE A FOUNDATION</div>${recipeRow('⌂','Shelter','8 wood · 4 stone','Shelter',{wood:8,stone:4},'build')}${recipeRow('⚗','Field laboratory','12 wood · 8 stone','Laboratory',{wood:12,stone:8},'build')}<p class="recipe-note">Shelters provide safety. A laboratory is required to unlock new scientific eras.</p>`;wireRecipes()}
 if(panel==='research'){content.innerHTML=`<div class="section-label">THE LONG ROAD BACK</div>${[['✧','Stone Age','You have awoken. Learn to make tools.'],['⚒','Bronze Age','Research metallurgy and build a laboratory.'],['⚙','Iron Age','Forge stronger tools and prepare for industry.'],['⌁','Industrial Age','Harness steam and rebuild at scale.'],['⌘','Modern Civilization','Reconnect the knowledge of humanity.']].map((x,i)=>`<div class="tech-row ${i===state.level-1?'current':i>=state.level?'locked':''}"><div class="tech-icon">${x[0]}</div><div><b>${x[1]} ${i===state.level-1?'· CURRENT':''}</b><p>${x[2]}</p></div></div>`).join('')}<button class="action-btn" id="study-btn" style="width:100%;margin-top:8px">${state.buildings.includes('Laboratory')?'STUDY · +10 SCIENCE':'NEED A LABORATORY'}</button><p class="recipe-note">Science leads the way back. Build a laboratory to study ancient fragments and advance your era.</p>`;document.querySelector('#study-btn').onclick=()=>{if(!state.buildings.includes('Laboratory'))return showToast('A FIELD LABORATORY IS NEEDED');state.science+=10;if(state.science>=30&&state.level===1){state.level=2;state.science=0;showToast('ERA ADVANCED · BRONZE AGE DISCOVERED')}else showToast('+10 SCIENCE · KNOWLEDGE RESTORED');updateHud();renderPanel('research')}}}
function recipeRow(icon,name,cost,id,needs,kind='craft'){const can=Object.entries(needs).every(([k,v])=>state[k]>=v)&&(kind==='craft'?!state.tools.includes(id):!state.buildings.includes(id));return `<div class="recipe"><div class="recipe-icon">${icon}</div><div class="recipe-info"><b>${name}</b><small>${state.tools.includes(id)||state.buildings.includes(id)?'Already crafted':cost}</small></div><button class="action-btn" data-make="${id}" data-kind="${kind}" ${can?'':'disabled'}>${state.tools.includes(id)||state.buildings.includes(id)?'DONE':kind==='build'?'BUILD':'CRAFT'}</button></div>`}
function wireRecipes(){document.querySelectorAll('[data-make]').forEach(btn=>btn.onclick=()=>{const id=btn.dataset.make,kind=btn.dataset.kind;const recipes={'Stone axe':{wood:2,stone:2},'Stone knife':{wood:1,stone:2},Campfire:{wood:3,stone:1},Shelter:{wood:8,stone:4},Laboratory:{wood:12,stone:8}};const needs=recipes[id];if(!Object.entries(needs).every(([k,v])=>state[k]>=v))return;for(const [k,v]of Object.entries(needs))state[k]-=v;if(kind==='craft'){state.tools.push(id);if(id==='Campfire')state.buildings.push(id)}else{state.buildings.push(id);if(id==='Shelter')placeBuilding('shelter');if(id==='Laboratory')placeBuilding('lab')}state.science+=id.includes('Stone')?4:2;showToast(`${id.toUpperCase()} ${kind==='build'?'BUILT':'CRAFTED'}`);updateHud();renderPanel(activePanel);updateResources()})}
function placeBuilding(kind){const g=new THREE.Group();if(kind==='shelter'){const base=new THREE.Mesh(new THREE.BoxGeometry(3.2,1.9,2.5),mat('#9a7652'));base.position.y=.95;g.add(base);const roof=new THREE.Mesh(new THREE.ConeGeometry(2.4,1.8,4),mat('#806348'));roof.position.y=2.7;roof.rotation.y=Math.PI/4;roof.scale.set(1,1,.75);g.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(.8,1.3,.12),mat('#4b382c'));door.position.set(0,.65,1.27);g.add(door)}else{const table=new THREE.Mesh(new THREE.BoxGeometry(2,.18,1),mat('#907453'));table.position.y=1;g.add(table);for(let x of [-.8,.8])for(let z of [-.35,.35]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.07,.08,1,6),materials.wood);leg.position.set(x,.5,z);g.add(leg)}const flask=new THREE.Mesh(new THREE.CylinderGeometry(.17,.22,.5,8),mat('#74a6a0'));flask.position.set(.35,1.34,0);g.add(flask)}g.position.set(player.position.x+3,0,player.position.z+2);g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(g)}
function updateResources(){updateHud();for(const t of resourceTypes){const el=document.querySelector(`#count-${t}`);if(el)el.textContent=state[t]}}
function gather(){if(!nearest||!nearest.active)return;const node=nearest;node.active=false;node.mesh.visible=false;for(const[k,v]of Object.entries(kinds[node.type].yield))state[k]+=v;state.science+=1;showToast(`+${Object.values(kinds[node.type].yield)[0]} ${node.type.toUpperCase()} · +1 SCIENCE`);nearest=null;document.querySelector('#interaction-prompt').classList.remove('show');updateResources();if(activePanel)renderPanel(activePanel);setTimeout(()=>{node.active=true;node.mesh.visible=true},26000)}

